(function(){
const defaults={horses:[{name:'Akhan',breed:'Ahalteke'},{name:'Kanun',breed:'Ahalteke'}],water:{base:1000,used:800},energy:{base:100,used:85,solar:25},waste:{total:180,compost:120},stable:{temperature:22,humidity:55,limitTemp:28,limitHumidity:75},pasture:[],analysisGoals:{water:20,energy:30,waste:80},stableSim:{tank:70,tankLimit:25,vent:65,light:45,power:2.4},compostPlan:{yield:55,sold:70,price:0.6,cost:0.12,fixed:500,days:365},solarPlan:{panels:20,watts:450,sun:5,efficiency:80,selfUse:80,investment:35000,maintenance:300},rain:{roof:500,rainfall:250,efficiency:80,demand:200},cost:{water:5,energy:0.5,days:365}};
let data,storageWarning=false;try{const stored=JSON.parse(localStorage.getItem('ecohorse-v1')||'{}');data=structuredClone(defaults);for(const k of Object.keys(defaults)){if(Array.isArray(defaults[k])){if(Array.isArray(stored?.[k]))data[k]=stored[k].filter(v=>v&&typeof v==='object'&&!Array.isArray(v))}else if(stored?.[k]&&typeof stored[k]==='object'){for(const field of Object.keys(defaults[k])){const v=stored[k][field];if(typeof v==='number'&&Number.isFinite(v))data[k][field]=v}}}for(const key of Object.keys(data.analysisGoals))if(data.analysisGoals[key]<1||data.analysisGoals[key]>100)data.analysisGoals[key]=defaults.analysisGoals[key]}catch{data=structuredClone(defaults);storageWarning=true}
const save=()=>{try{localStorage.setItem('ecohorse-v1',JSON.stringify(data));storageWarning=false}catch{storageWarning=true;alert('Maglumatlar brauzeriň ýadynda saklanmady. JSON eksport arkaly nusga alyň.')}};
const names=['Dolandyryş paneli','Atlar','Suw serişdeleri','Energiýa','Galyndylar','Akylly seljerme','Hasabat','Akylly athana','Öri meýdanlary','Ykdysadyýet','Sanly toplum','Hakaton tanyşdyryşy'],icons=['▦','♘','◉','ϟ','♻','✧','▤','⌂','♧','₼','▧','▣'];
let page=0,edit=-1,search='',simTimer=null,simHistory=[],pastureEdit=-1,reportDays=365,presentationIndex=0;
const $=id=>document.getElementById(id),fmt=n=>Number(n.toFixed(1)).toLocaleString('en-US'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=(a,b)=>b>0?a/b*100:0;
const card=(t,v,d)=>`<article class="card"><small>${t}</small><div class="metric">${v}</div><div class="muted">${d}</div></article>`;
function metrics(){let w=data.water,e=data.energy,g=data.waste;return {w:w.base-w.used,e:e.base-e.used+e.solar,g:g.compost,pw:pct(w.base-w.used,w.base),pe:pct(e.base-e.used+e.solar,e.base),pg:pct(g.compost,g.total)}}
function cards(){let m=metrics();const stats=[['◉','Suw tygşytlamasy',fmt(m.w)+' L','Günde','water',2],['ϟ','Elektrik torundan azalyş',fmt(m.e)+' kWh','Günde','energy',3],['♻','Komposta gönükdirilen ders',fmt(m.g)+' kg','Günde','waste',4],['♘','Hasaba alnan atlar',data.horses.length,'Sanly atçylyk hasaby','horses',1]];return `<div class="grid kpi-grid">${stats.map(([i,t,v,d,k,p])=>`<article class="card kpi"><div class="kpi-top"><span class="kpi-icon ${k}">${i}</span><button class="link-btn" aria-label="${t} — giňişleýin" onclick="go(${p})">↗</button></div><small>${t}</small><div class="metric">${v}</div><div class="muted">${d}</div></article>`).join('')}</div>`}
const progress=(t,v)=>`<div>${t} <b style="float:right">${fmt(v)}%</b></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,v))}%"></i></div>`;
function compare(title,unit,base,now,target){return `<article class="card compare"><div class="section-head"><h3>${title}</h3><button class="link-btn" onclick="go(${target})">Giňişleýin →</button></div>${[['Başlangyç',base],['Häzirki',now]].map(([label,v],i)=>`<div class="compare-row"><span>${label}</span><div class="track"><i class="${i?'current':'baseline'}" style="width:${Math.max(0,v)/Math.max(1,base,now)*100}%"></i></div><b>${fmt(v)} ${unit}</b></div>`).join('')}</article>`}
function dashboard(){let m=metrics(),c=data.cost,money=m.w/1000*c.water+m.e*c.energy;return `<section class="hero home-hero"><div class="hero-content"><span class="eyebrow">SMART & GREEN · 2026</span><h1>Bedewler bilen<br>ýaşyl geljege.</h1><p>Atçylyk toplumynyň serişdelerini dolandyryň, isripi azaldyň we ekologik peýdany ölçäň.</p><div class="hero-actions"><button onclick="go(10)">Sanly toplumy aç →</button><button class="secondary" onclick="go(11)">Tanyşdyryş</button></div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 360 220"><circle cx="245" cy="78" r="50" fill="#d5eab0"/><path d="M0 165Q90 75 180 160T360 135V220H0Z" fill="#518568"/><path d="M0 190Q120 120 240 185T360 160V220H0Z" fill="#9abb80"/><path d="M135 190L153 144 147 109 170 72 183 88 195 62 204 91 239 112 230 133 204 128 188 150 204 190Z" fill="#f5e8cb"/><path d="M153 144L147 109 170 72 183 88 164 119Z" fill="#c6a77b"/><circle cx="208" cy="108" r="3" fill="#173d30"/></svg></div></section><div class="section-head"><h3>Gündelik görkezijiler</h3><span class="pill">L / kWh / kg</span></div>${cards()}<div class="cols home-charts">${compare('Suw sarp edilişi','L',data.water.base,data.water.used,2)}${compare('Elektrik torundan sarp ediliş','kWh',data.energy.base,data.energy.used-data.energy.solar,3)}</div><div class="cols home-charts"><article class="card"><h3>Ýyllyk ekologik çaklama</h3><div class="annual"><div><small>Suw</small><strong>${fmt(m.w*365/1000)} m³</strong></div><div><small>Elektrik</small><strong>${fmt(m.e*365)} kWh</strong></div><div><small>Komposta gönükdirilen ders</small><strong>${fmt(m.g*365/1000)} t</strong></div><div><small>Mümkin bolan tygşytlylyk</small><strong>${fmt(money*365)} TMT</strong></div></div><small>365 deň gün boýunça. Maýa çykdajylary aýrylmady.</small></article><article class="card"><div class="section-head"><h3>Ekologik ösüş</h3><span class="pill">Eco Score ${analysisModel().score===null?"—":fmt(analysisModel().score)+"/100"}</span></div>${progress('Suw tygşytlamasy',m.pw)}${progress('Elektrik torundan azalyş',m.pe)}${progress('Komposta gönükdirilen ders',m.pg)}<button class="link-btn" onclick="go(5)">Akylly seljermä geç →</button></article></div><h3>Çalt geçiş</h3><div class="quick-grid">${[11,10,1,2,3,4,7,8,9,6].map(i=>`<button class="quick" onclick="go(${i})"><span>${icons[i]}</span>${names[i]}<b>→</b></button>`).join('')}</div><p class="home-note">Başlangyç maglumatlar görkezme maksatly.</p>`}
const configs={water:[['base','Başlangyç suw (L/gün)'],['used','Häzirki suw (L/gün)']],energy:[['base','Başlangyç elektrik (kWh/gün)'],['used','Häzirki jemi elektrik (kWh/gün)'],['solar','Ulanylan Gün energiýasy (kWh/gün)']],waste:[['total','Jemi ders (kg/gün)'],['compost','Komposta gönükdirilen ders (kg/gün)']],stable:[['temperature','Temperatura (°C)',-50,70],['humidity','Çyglylyk (%)',0,100],['limitTemp','Temperatura duýduryş çägi (°C)',-50,70],['limitHumidity','Çyglylyk duýduryş çägi (%)',0,100]],cost:[['water','Suw bahasy (TMT/m³)'],['energy','Elektrik bahasy (TMT/kWh)'],['days','Döwür (gün)',1,3650]]};
function fields(k){return `<form class="card" id="form" data-key="${k}"><h3>Maglumatlary giriziň</h3>${configs[k].map(([n,t,min=0,max=1000000000])=>`<label for="${n}">${t}</label><input id="${n}" name="${n}" type="number" min="${min}" max="${max}" step="${n==='days'?1:'any'}" required value="${esc(data[k][n])}">`).join('')}<p id="err" style="color:#a43b32;margin-top:10px"></p><button>Ýatda sakla we hasapla</button></form>`}
const horseFields=[['name','Ady'],['breed','Tohumy'],['age','Ýaşy (ýyl)','number'],['weight','Agramy (kg)','number'],['health','Weterinariýa belligi'],['feed','Iýmitlendiriş meýilnamasy'],['passport','Pasport belgisi'],['sex','Jynsy'],['color','Reňki'],['stable','Athana belgisi']];
function horsePhoto(h){return typeof h.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(h.photo)?h.photo:''}
function horsePicture(h){const src=horsePhoto(h);return src?`<img class="horse-photo" src="${src}" alt="${esc(h.name||'At')}">`:'<div class="horse-placeholder"><span>♘</span><small>Surat goşulmady</small></div>'}
async function readHorsePhoto(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error('JPG, PNG ýa-da WebP (15 MB çenli) saýlaň.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1000/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.78)}finally{URL.revokeObjectURL(url)}}
function horses(){let h=data.horses[edit]||{};return `<div class="cols"><form id="horseForm" class="card"><h3>${edit<0?'Täze at goş':'At maglumatlaryny üýtget'}</h3><div id="horsePreview">${horsePicture(h)}</div><label for="horsePhoto">At suraty (JPG, PNG, WebP)</label><input id="horsePhoto" type="file" accept="image/jpeg,image/png,image/webp"><p class="muted">Surat awtomatik kiçeldilýär we şu brauzerde saklanýar.</p><button type="button" class="link-btn" id="clearHorsePhoto">Suraty aýyr</button><p id="photoError" role="alert" class="muted"></p>${horseFields.map(([n,t,type='text'],i)=>`<label for="horse-${n}">${t}</label><input id="horse-${n}" name="${n}" type="${type}" ${i<2?'required':''} ${type==='number'?`min="${n==='weight'?1:0}" step="any" ${n==='age'?'max="60"':''}`:'maxlength="200"'} value="${esc(h[n])}">`).join('')}<br><br><button>Ýatda sakla</button>${edit>=0?' <button type="button" onclick="go(1)">Ýatyr</button>':''}</form><div class="card"><h3>Atlaryň sanawy (${data.horses.length})</h3><form id="horseSearch"><label for="horseQuery">Ady, tohumy ýa-da pasport belgisi boýunça gözle</label><input id="horseQuery" value="${esc(search)}"><br><br><button>Gözle</button> <button type="button" onclick="clearSearch()">Arassala</button></form><br><div class="horse-list">${data.horses.map((h,i)=>({...h,i})).filter(h=>[h.name,h.breed,h.passport].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))).map(h=>{let i=h.i;return `<article class="horse-item horse-catalog-item">${horsePicture(h)}<h3>${esc(h.name)}</h3><p>${esc(h.breed)} · ${esc(h.age||'—')} ýyl · ${esc(h.weight||'—')} kg</p><p>${esc(h.health||'Bellik ýok')} · ${esc(h.feed||'Meýilnama ýok')}</p><p><small>Pasport: ${esc(h.passport||'—')} · Athana: ${esc(h.stable||'—')}</small></p><button onclick="showPassport(${i})">Pasport</button><button onclick="editHorse(${i})">Üýtget</button><button class="danger" onclick="removeHorse(${i})">Poz</button></article>`}).join('')||'At tapylmady'}</div></div></div>`}
function rainModel(){const r=data.rain;const gross=r.roof*r.rainfall*r.efficiency/100/1000;const usable=Math.min(gross,r.demand*365/1000);return {gross,usable,money:usable*data.cost.water}}
function waterLab(){const r=data.rain,m=rainModel(),w=data.water;return `<section class="card" style="margin-top:18px"><div class="section-head"><h3>Ýagyş suwuny ýygnamak</h3><span class="pill">Green Technology</span></div><p class="muted">Athana üçeginden ýygnalýan suwy arassaçylyk we beýleki agyz suwy bolmadyk işler üçin ulanmak boýunça çaklama.</p><form id="rainForm"><div class="grid">${[['roof','Üçek meýdany (m²)',0,1000000],['rainfall','Ýyllyk ygalyň mukdary (mm)',0,10000],['efficiency','Ýygnama netijeliligi (%)',0,100],['demand','Agyz suwy bolmadyk işler üçin zerurlyk (L/gün)',0,1000000]].map(([k,l,min,max])=>`<div><label for="rain-${k}">${l}</label><input id="rain-${k}" name="${k}" type="number" min="${min}" max="${max}" step="any" required value="${esc(r[k])}"></div>`).join('')}</div><button>Çaklamany hasapla</button></form><div class="grid">${card('Ýygnalyp bilinjek suw',fmt(m.gross)+' m³','Ýylda')}${card('Çaklanylýan ulanyş',fmt(m.usable)+' m³','Ýyllyk zerurlyk bilen çäklendirilen')}${card('Goşmaça mümkin bolan tygşytlylyk',fmt(m.money)+' TMT','Maýa we hyzmat çykdajylary aýrylmady')}</div><p class="notice">Formula: üçek meýdany × ygal × netijelilik ÷ 1000. Ýyllyk hasap möwsümleýin tapawutlary we bak göwrümini hasaba almaýar. Bu çaklama bar bolan tygşytlylyga goşulmaýar: iki gezek hasaplamagyň öňüni almak üçin aýratyn görkezilýär. Atlaryň agyz suwuny çäklendirmäň; ýygnalan suw degişli barlag we arassalaýyş bolmazdan agyz suwy hökmünde ulanylmaly däl.</p></section><section class="card" style="margin-top:18px"><h3>Suw tygşytlylygynyň ssenariýasy</h3><p>Häzirki sarp ediliş: ${fmt(w.used)} L/gün. Diňe isrip we agyz suwy bolmadyk işler boýunça mümkin bolan azalyşy barlaň.</p><label for="scenario">Goşmaça azalyş: <b id="scenarioPct">0%</b></label><input id="scenario" type="range" min="0" max="30" value="0" step="1"><div class="grid"><article><small>Goşmaça suw tygşytlylygy</small><div class="metric" id="scenarioWater">0 m³</div></article><article><small>Ýyllyk çykdajy azalyşy</small><div class="metric" id="scenarioMoney">0 TMT</div></article></div><small>Diňe ssenariýa; ölçenen netije däl.</small></section>`}
function solarModel(){const p=data.solarPlan;const capacity=p.panels*p.watts/1000;const generation=capacity*p.sun*p.efficiency/100*365;const demand=Math.max(0,data.energy.used-data.energy.solar)*365;const used=Math.min(generation*p.selfUse/100,demand);const gross=used*data.cost.energy;const net=gross-p.maintenance;return {capacity,generation,used,gross,net,payback:net>0?p.investment/net:null}}
function solarLab(){const p=data.solarPlan,m=solarModel();return `<section class="card" style="margin-top:18px"><div class="section-head"><h3>Gün energiýasy — maýa goýum meýilnamasy</h3><span class="pill">Green Energy</span></div><p class="muted">Täze paneller üçin çaklama. Öňki Gün energiýasyndan aýratyn hasaplanýar.</p><form id="solarForm"><div class="grid">${[['panels','Panelleriň sany',0,100000,1],['watts','Bir paneliň kuwwaty (W)',0,5000,'any'],['sun','Güneşli ekwiwalent sagat (sagat/gün)',0,24,'any'],['efficiency','Ulgamyň netijelilik koeffisiýenti (%)',0,100,'any'],['selfUse','Öz zerurlygy üçin ulanyş (%)',0,100,'any'],['investment','Başlangyç maýa goýumy (TMT)',0,1000000000,'any'],['maintenance','Ýyllyk hyzmat çykdajysy (TMT)',0,1000000000,'any']].map(([k,l,min,max,step])=>`<div><label for="solar-${k}">${l}</label><input id="solar-${k}" name="${k}" type="number" min="${min}" max="${max}" step="${step}" required value="${esc(p[k])}"></div>`).join('')}</div><button>Hasapla we ýatda sakla</button></form><div class="grid">${card('Gurnalan kuwwat',fmt(m.capacity)+' kWp','Nominal kuwwat')}${card('Ýyllyk önümçilik',fmt(m.generation)+' kWh','Çaklama')}${card('Elektrik torundan goşmaça azalyş',fmt(m.used)+' kWh','Öz sarp edilişi bilen çäklenen')}${card('Arassa ýyllyk peýda',fmt(m.net)+' TMT','Hyzmat çykdajysy aýryldy')}${card('Öwezini doluş möhleti',m.payback===null?'Hasaplanmaýar':fmt(m.payback)+' ýyl',m.payback===null?'Arassa peýda položitel däl':'Ýönekeý hasaplama')}</div>${progress('Önümçiligiň ýerinde peýdalanylýan paýy',pct(m.used,m.generation))}<p class="notice">Formula: kuwwat × ekwiwalent Gün sagady × netijelilik × 365. Bu nusga modelidir, ýerli meteorologiýa maglumatlary, möwsümleýin tapawutlar, degradirlenme we maliýeleşdiriş çykdajylary girizilmedi. Elektrik satuwyndan girdeji hasaplanmaýar. Netije bar bolan tygşytlylyga goşulmaýar.</p></section>`}
function compostModel(){const p=data.compostPlan;const input=data.waste.compost*p.days;const output=input*p.yield/100;const sold=output*p.sold/100;const revenue=sold*p.price;const cost=input*p.cost+p.fixed;return {input,output,sold,retained:output-sold,revenue,cost,net:revenue-cost,remaining:(data.waste.total-data.waste.compost)*p.days}}
function compostLab(){const p=data.compostPlan,m=compostModel();return `<section class="card" style="margin-top:18px"><div class="section-head"><h3>Organiki dökün — önümçilik meýilnamasy</h3><span class="pill">Eco Waste</span></div><p class="muted">Komposta gönükdirilen dersden taýýarlanyp bilinjek döküniň we ykdysady netijäniň çaklamasy.</p><div class="grid"><article class="notice"><small>01 · Çig mal</small><h3>${fmt(m.input/1000)} t</h3>Ders ýygnamak</article><article class="notice"><small>02 · Gaýtadan işlemek</small><h3>${fmt(p.yield)}%</h3>Çaklanylýan taýýar önüm paýy</article><article class="notice"><small>03 · Taýýar önüm</small><h3>${fmt(m.output/1000)} t</h3>Organiki dökün</article></div><form id="compostForm"><div class="grid">${[['yield','Taýýar kompostyň agram paýy (%)',0,100,'any'],['sold','Satuwa çykarylýan paý (%)',0,100,'any'],['price','Satuw bahasy (TMT/kg)',0,100000,'any'],['cost','Gaýtadan işlemegiň üýtgeýän çykdajysy (TMT/kg çig mal)',0,100000,'any'],['fixed','Döwür boýunça hemişelik çykdajy (TMT)',0,1000000000,'any'],['days','Hasaplama döwri (gün)',1,3650,1]].map(([k,l,min,max,step])=>`<div><label for="compost-${k}">${l}</label><input id="compost-${k}" name="${k}" type="number" min="${min}" max="${max}" step="${step}" required value="${esc(p[k])}"></div>`).join('')}</div><button>Hasapla we ýatda sakla</button></form><div class="grid">${card('Taýýar dökün',fmt(m.output/1000)+' t',p.days+' gün boýunça')}${card('Satuwa gönükdirilýän dökün',fmt(m.sold/1000)+' t','Çaklama')}${card('Toplumyň özünde galýan dökün',fmt(m.retained/1000)+' t','Peýdalanmak mümkinçiligi')}${card('Satuwdan girdeji',fmt(m.revenue)+' TMT','Çaklama')}${card('Önümçilik çykdajysy',fmt(m.cost)+' TMT','Girizilen çykdajylar')}${card('Arassa amal netijesi',fmt(m.net)+' TMT','Maýa goýumy we salgytlar aýrylmady')}</div>${progress('Komposta gönükdirilen ders',pct(data.waste.compost,data.waste.total))}<p class="notice">Komposta gönükdirilmedik ders: ${fmt(m.remaining/1000)} t. Taýýar kompostyň agramy = çig mal × girizilen agram paýy. Bu paý we bahalar diňe mysal bolup, hakyky önümçilik ölçegleri bilen çalşylmaly. Kompostyň ulanyşa ýa-da satuwa ýaramlylygy degişli sanitariýa barlaglary bilen kesgitlenmeli. Galyndynyň azalmagy boýunça CO₂ çaklamasy hasaplanmaýar.</p></section>`}
function stableLab(){const a=data.stableSim;return `<section class="card" style="margin-top:18px"><div class="section-head"><h3>Akylly athana — IoT dolandyryş merkezi</h3><span class="pill">SIMULÝASIÝA</span></div><p class="muted">Hakyky datçikler birikdirilmedi. Görkezijiler diňe görkezme üçin döredilýär.</p><div class="grid"><article class="card"><small>Suw bakynyň derejesi</small><div class="metric" id="simTank"></div><div class="bar"><i id="simTankBar"></i></div></article><article class="card"><small>Temperatura</small><div class="metric" id="simTemp"></div></article><article class="card"><small>Çyglylyk</small><div class="metric" id="simHumidity"></div></article><article class="card"><small>Howa çalşygy (simulýasiýa)</small><div class="metric" id="simVent"></div></article><article class="card"><small>Yşyklandyryş (simulýasiýa)</small><div class="metric" id="simLight"></div></article><article class="card"><small>Elektrik kuwwaty</small><div class="metric" id="simPower"></div></article></div><div class="notice" id="simAlerts" role="status"></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button onclick="startStableSim()">Simulýasiýany başlat</button><button onclick="stopStableSim()">Duruz</button><button onclick="stableScenario()">Suw azalmasyny görkez</button><button onclick="resetStableSim()">Başlangyç ýagdaýa getir</button></div><p id="simStatus" class="muted" style="margin-top:12px">Simulýasiýa duruzylan.</p><h3>Soňky 20 ölçeg — suw derejesi (%)</h3><svg id="simChart" viewBox="0 0 600 150" role="img" aria-label="Suw derejesiniň simulýasiýa diagrammasy" style="width:100%;max-height:200px;background:#f2f5f1;border-radius:10px"></svg><form id="stableSimForm"><div class="grid">${[['tank','Başlangyç suw derejesi (%)',0,100],['tankLimit','Suw duýduryş çägi (%)',0,100],['vent','Howa çalşygy (%)',0,100],['light','Yşyklandyryş (%)',0,100],['power','Elektrik kuwwaty (kW)',0,10000]].map(([k,l,min,max])=>`<div><label for="sim-${k}">${l}</label><input id="sim-${k}" name="${k}" type="number" min="${min}" max="${max}" step="any" required value="${esc(a[k])}"></div>`).join('')}</div><button>Simulýasiýa sazlamalaryny sakla</button></form><p class="notice">Duýduryş çäkleri ulanyjy tarapyndan saýlanýar; weterinariýa standarty däl. Ulgam hakyky enjamlary dolandyrmaýar. Atlaryň suw üpjünçiligini kesmäň.</p></section>`}
let simReading=null;
function drawStable(){if(!$('simTank'))return;const a=simReading||{...data.stableSim,temperature:data.stable.temperature,humidity:data.stable.humidity};const alerts=[];if(a.tank<=data.stableSim.tankLimit)alerts.push('Suw derejesi pes: baky we suw üpjünçiligini barlaň.');if(a.temperature>data.stable.limitTemp)alerts.push('Temperatura bellenen çäkden ýokary.');if(a.humidity>data.stable.limitHumidity)alerts.push('Çyglylyk bellenen çäkden ýokary.');$('simTank').textContent=fmt(a.tank)+'%';$('simTankBar').style.width=a.tank+'%';$('simTemp').textContent=fmt(a.temperature)+' °C';$('simHumidity').textContent=fmt(a.humidity)+'%';$('simVent').textContent=fmt(a.vent)+'%';$('simLight').textContent=fmt(a.light)+'%';$('simPower').textContent=fmt(a.power)+' kW';$('simAlerts').textContent=alerts.join(' ')||'Simulýasiýa: bellenen çäklerden çykma ýok.';$('simAlerts').style.background=alerts.length?'#f8dfd8':'#edf4e9';$('simStatus').textContent=simTimer?'Simulýasiýa işleýär · her 2 sekuntda':'Simulýasiýa duruzylan.';const h=simHistory.length?simHistory:[a.tank];const points=h.map((v,i)=>[30+i*540/19,130-v*1.1].join(',')).join(' ');$('simChart').innerHTML='<path d="M30 20H570M30 75H570M30 130H570" stroke="#cddbd0" fill="none"/><g fill="#688276" font-size="10"><text x="4" y="23">100</text><text x="10" y="78">50</text><text x="16" y="133">0</text></g><line x1="30" x2="570" y1="'+(130-data.stableSim.tankLimit*1.1)+'" y2="'+(130-data.stableSim.tankLimit*1.1)+'" stroke="#b45442" stroke-dasharray="5 4"/><polyline points="'+points+'" fill="none" stroke="#29845b" stroke-width="3"/>'+h.map((v,i)=>'<circle cx="'+(30+i*540/19)+'" cy="'+(130-v*1.1)+'" r="3" fill="#29845b"/>').join('')}
function stopStableSim(){if(simTimer!==null)clearInterval(simTimer);simTimer=null;drawStable()}
function resetStableSim(){stopStableSim();simReading={...data.stableSim,temperature:data.stable.temperature,humidity:data.stable.humidity};simHistory=[simReading.tank];drawStable()}
function tickStable(){if(!simReading)resetStableSim();const a=simReading,clamp=(v,l,h)=>Math.min(h,Math.max(l,v));a.tank=clamp(a.tank-Math.random()*2,0,100);a.temperature=clamp(a.temperature+(Math.random()-.45)*.8,-50,70);a.humidity=clamp(a.humidity+(Math.random()-.5)*2,0,100);a.power=Math.max(0,data.stableSim.power*(.9+Math.random()*.2));simHistory.push(a.tank);simHistory=simHistory.slice(-20);drawStable()}
function startStableSim(){if(simTimer!==null)return;if(!simReading)resetStableSim();simTimer=setInterval(tickStable,2000);drawStable()}
function stableScenario(){if(!simReading)resetStableSim();simReading.tank=Math.max(0,data.stableSim.tankLimit-5);simHistory.push(simReading.tank);simHistory=simHistory.slice(-20);drawStable()}

function analysisModel(){
const m=metrics(),g=data.analysisGoals,p=pastureTotals(),a=data.stableSim,st=data.stable,items=[],goals=[{name:'Suw tygşytlamasy',value:m.pw,target:g.water,valid:data.water.base>0,page:2},{name:'Elektrik torundan azalyş',value:m.pe,target:g.energy,valid:data.energy.base>0,page:3},{name:'Komposta gönükdirilen paý',value:m.pg,target:g.waste,valid:data.waste.total>0,page:4}];
const add=(priority,title,detail,action,page)=>items.push({priority,title,detail,action,page});
if(a.tank<=a.tankLimit)add(0,'Suw üpjünçiligini barlamak','Simulýasiýanyň başlangyç suw derejesi bellenen çäkde ýa-da ondan pes.','Hakyky baky we agyz suwunyň elýeterliligini barlaň.',7);
if(st.temperature>st.limitTemp||st.humidity>st.limitHumidity)add(0,'Athananyň şertleri','Girizilen temperatura ýa-da çyglylyk ulanyjynyň çäginden ýokary.','Howa çalşygyny we hakyky ölçegleri barlaň.',7);
if(p.count>data.horses.length)add(0,'Atlaryň paýlanyşy','Meýdanlara paýlanan atlaryň sany sanawdaky atlardan köp.','Hasaba alyş maglumatlaryny deňeşdiriň.',8);
if(data.pasture.some(x=>x.status!=='active'&&x.status&&Number(x.count)>0))add(0,'Dynç alýan meýdan','Ýapyk ýa-da dynç alýan meýdanda at hasaba alnan.','Paýlanyşy düzedip, meýdan ýagdaýyny barlaň.',8);
for(const t of goals){if(!t.valid)add(1,t.name+' — maglumat ýetmezçiligi','Başlangyç ýa-da jemi mukdar 0.','Hasaplamaga ýeterlik maglumat giriziň.',t.page);else if(t.value<t.target)add(1,t.name+' — maksada ýetilmedi',fmt(t.value)+'% / '+fmt(t.target)+'% maksat.',['Suw syzmalaryny we isripleri barlaň; agyz suwuny çäklendirmäň.','Elektrik sarp edýän enjamlary we Gün energiýasy meýilnamasyny seljeriň.','Howpsuz kompost meýilnamasyny we önümçilik şertlerini barlaň.'][t.page-2],t.page)}
if(data.pasture.some(x=>x.review&&x.review<=new Date().toISOString().slice(0,10)))add(1,'Öri meýdanlaryny gözden geçirmek','Bellenen gözden geçiriş senesi ýetdi.','Meýdanlaryň hakyky ýagdaýyny barlaň.',8);
const solar=solarModel(),rain=rainModel(),compost=compostModel();
if(solar.net>0)add(2,'Gün energiýasy mümkinçiligi',fmt(solar.net)+' TMT/ýyl çaklama.','Maýa goýumyny hakyky nyrhlar bilen deňeşdiriň.',3);
if(rain.usable>0)add(2,'Ýagyş suwuny ýygnamak',fmt(rain.usable)+' m³/ýyl çaklama.','Bak göwrümini, möwsümleýin ygaly we suwuň hilini barlaň.',2);
if(compost.net<0)add(1,'Kompost çykdajylary',fmt(compost.net)+' TMT amal netijesi.','Satuw bahasyny, çykdajylary we önümçilik maglumatlaryny barlaň.',4);
else if(compost.net>0)add(2,'Kompost mümkinçiligi',fmt(compost.net)+' TMT amal netijesi ('+data.compostPlan.days+' gün).','Satuwa ýaramlylygy we bazar islegini tassyklaň.',4);
const valid=goals.filter(t=>t.valid);const score=valid.length?valid.reduce((sum,t)=>sum+Math.min(100,Math.max(0,t.value/t.target*100)),0)/valid.length:null;
return {goals,score,items:items.sort((a,b)=>a.priority-b.priority),covered:valid.length}}
function analysis(){const a=analysisModel(),g=data.analysisGoals;return `<section class="hero"><h1>Akylly seljerme merkezi</h1><p>Girizilen maglumatlar boýunça ekologik maksatlara ýetilişi we ileri tutulmaly işleri kesgitläň.</p><span class="pill">Düzgünlere esaslanýan seljerme</span></section><div class="grid">${card('Içerki maksat görkezijisi',a.score===null?'—':fmt(a.score)+' / 100',a.covered+'/3 ugur boýunça')}${card('Ilkinji nobatda barlamaly',a.items.filter(i=>i.priority===0).length,'Duýduryş')}${card('Kämilleşdirmeli işler',a.items.filter(i=>i.priority===1).length,'Meýilnama')}${card('Mümkinçilikler',a.items.filter(i=>i.priority===2).length,'Çaklama')}</div><section class="card"><h3>Ekologik maksatlar</h3><form id="goalsForm"><div class="grid">${[['water','Suw tygşytlamasy (%)'],['energy','Elektrik torundan azalyş (%)'],['waste','Komposta gönükdirilen paý (%)']].map(([k,l])=>`<div><label for="goal-${k}">${l}</label><input id="goal-${k}" name="${k}" type="number" min="1" max="100" step="any" required value="${esc(g[k])}"></div>`).join('')}</div><button>Maksatlary sakla</button></form><br>${a.goals.map(t=>`<div style="margin:16px 0"><strong>${t.name}</strong><p>${t.valid?fmt(t.value)+'% / '+fmt(t.target)+'% maksat':'Maglumat ýeterlik däl'}</p>${t.valid?progress('Maksada ýetiliş',Math.min(100,Math.max(0,t.value/t.target*100))):''}<button class="link-btn" onclick="go(${t.page})">Maglumatlary üýtget →</button></div>`).join('')}<p class="notice">Içerki görkeziji: maglumat bar ugurlaryň maksatlara ýetilişiniň (0–100 aralygynda çäklendirilen) deň agramly ortaçasy. Maksatlar ulanyjy tarapyndan kesgitlenýär; bu resmi ekologik baha ýa-da sertifikat däl.</p></section><section class="card" style="margin-top:18px"><h3>Ileri tutulmaly işler</h3>${a.items.map(i=>`<article class="horse-item" style="margin-bottom:12px;border-left:5px solid ${['#b45442','#ba9048','#39865b'][i.priority]}"><small>${['01 · Ilkinji nobatda barla','02 · Kämilleşdir','03 · Mümkinçilik'][i.priority]}</small><h3 style="margin-top:8px">${i.title}</h3><p>${i.detail}</p><p>${i.action}</p><button onclick="go(${i.page})">Degişli bölümi aç →</button></article>`).join('')||'<p>Häzirki düzgünler boýunça goşmaça iş tapylmady.</p>'}<p class="muted">Bu daşarky emeli aň modeli däl. Maglumatlar girizilen sanlara we simulýasiýa sazlamalaryna bagly. Çaklamalar esasy tygşytlylyga goşulmaýar.</p></section>`}

function pastureTotals(){return data.pasture.reduce((a,p)=>{const area=Number(p.area)||0, count=Number(p.count)||0,water=area*(Number(p.irrigation)||0);a.area+=area;a.count+=count;a.water+=water;if(p.status==='rest')a.rest+=area;return a},{area:0,count:0,water:0,rest:0})}
function pasture(){let t=pastureTotals(),p=data.pasture[pastureEdit]||{},today=new Date().toISOString().slice(0,10);return `<div class="grid">${card('Jemi meýdan',fmt(t.area)+' ga','Hasaba alnan')}${card('Paýlanan atlar',t.count+' / '+data.horses.length,'Sanaw boýunça')}${card('Dynç alýan meýdan',fmt(t.rest)+' ga','Bellenen ýagdaý')}${card('Suwaryş meýilnamasy',fmt(t.water)+' m³','Bir suwaryş üçin')}</div><section class="card"><div class="section-head"><h3>Öri meýdanlarynyň sanly çyzgysy</h3><span class="pill">Green Pasture</span></div><p class="muted">Şertli çyzgy, GPS kartasy däl. Meýdany saýlap maglumatlaryny üýtgediň.</p><div class="grid">${data.pasture.map((a,i)=>`<button onclick="editPasture(${i})" style="min-height:130px;text-align:left;background:${a.status==='rest'?'#a37b43':a.status==='closed'?'#667b72':'#38784d'};border:3px solid #d6e8ca"><strong>${esc(a.name)}</strong><p style="margin:8px 0">${esc(a.area)} ga · ${esc(a.count)} at</p><small style="color:white">${a.status==='rest'?'Dynç alýar':a.status==='closed'?'Ýapyk':'Ulanylýar'}</small></button>`).join('')||'<p>Çyzgyny döretmek üçin meýdan goşuň.</p>'}</div></section><div class="cols" style="margin-top:18px"><form id="pastureForm" class="card"><h3>${pastureEdit<0?'Öri meýdany goş':'Meýdany üýtget'}</h3><label>Ady</label><input name="name" required maxlength="80" value="${esc(p.name)}"><label>Meýdany (ga)</label><input name="area" required type="number" min="0.01" step="any" value="${esc(p.area)}"><label>Paýlanan atlaryň sany</label><input name="count" required type="number" min="0" step="1" value="${esc(p.count??0)}"><label>Ýagdaýy</label><select name="status" style="width:100%;padding:10px;border:1px solid #cddbd0;border-radius:8px">${[['active','Ulanylýar'],['rest','Dynç alýar'],['closed','Ýapyk']].map(([k,l])=>`<option value="${k}" ${p.status===k?'selected':''}>${l}</option>`).join('')}</select><label>Dynç alyş meýilnamasy</label><input name="rest" maxlength="100" value="${esc(p.rest)}"><label>Gaýtadan gözden geçiriş senesi</label><input name="review" type="date" value="${esc(p.review)}"><label>Bir suwaryş üçin meýilnama (m³/ga)</label><input name="irrigation" required type="number" min="0" step="any" value="${esc(p.irrigation??0)}"><p id="pastureError" role="alert" style="color:#a43b32"></p><button>Ýatda sakla</button> ${pastureEdit>=0?'<button type="button" onclick="cancelPasture()">Ýatyr</button>':''}</form><div class="card"><h3>Meýdanlaryň sanawy</h3>${data.pasture.map((a,i)=>`<article class="horse-item"><h3>${esc(a.name)}</h3><p>${esc(a.area)} ga · ${esc(a.count)} at · ${fmt(a.count/a.area)} at/ga</p><p>${esc(a.rest||'Meýilnama ýok')}</p><p>Gözden geçiriş: ${esc(a.review||'Bellenmedik')}</p>${a.review&&a.review<=today?'<div class="notice">Gözden geçiriş wagty ýetdi.</div>':''}<p>Bir suwaryş: ${fmt(a.area*(Number(a.irrigation)||0))} m³</p><button onclick="editPasture(${i})">Üýtget</button> <button class="danger" onclick="removePasture(${i})">Poz</button></article>`).join('')||'Heniz meýdan goşulmady'}</div></div><p class="notice">${t.count>data.horses.length?'Duýduryş: paýlanan atlaryň sany hasaba alnan atlardan köp. ':''}At/ga diňe hasaplama, göterijilik ukyby ýerli ösümlik, toprak we howa şertlerine bagly. Suwaryş mukdary ulanyjynyň meýilnamasy, agronomik maslahat däl. Suw sarp edilişiniň esasy hasabyna awtomatik goşulmaýar.</p>`}

function twin(){const m=metrics(),p=pastureTotals();const sites=[{x:32,y:48,w:225,h:145,n:'Athana',v:data.horses.length+' at',page:7,c:'#e8d8b6',icon:'⌂'},{x:290,y:48,w:220,h:145,n:'Gün panelleri',v:fmt(data.energy.solar)+' kWh/gün',page:3,c:'#c1ddeb',icon:'ϟ'},{x:545,y:48,w:220,h:145,n:'Suw merkezi',v:fmt(data.water.used)+' L/gün',page:2,c:'#c4e5ed',icon:'◉'},{x:32,y:240,w:478,h:175,n:'Öri meýdanlary',v:fmt(p.area)+' ga · '+data.pasture.length+' meýdan',page:8,c:'#cce3b6',icon:'♧'},{x:545,y:240,w:220,h:175,n:'Kompost merkezi',v:fmt(data.waste.compost)+' kg/gün',page:4,c:'#e7d7b9',icon:'♻'}];return `<section class="hero"><h1>Atçylyk toplumynyň sanly modeli</h1><p>Bir çyzgyda ähli serişdeler we dolandyryş merkezleri. Desgany saýlap degişli bölüme geçiň.</p><span class="pill">Digital Twin prototipi</span></section><section class="card"><div class="section-head"><h3>Interaktiw toplum çyzgysy</h3><span class="pill">Şertli ýerleşiş</span></div><svg viewBox="0 0 800 460" style="width:100%;height:auto;background:#e7efe2;border-radius:15px" aria-label="Atçylyk toplumynyň şertli çyzgysy"><rect x="15" y="15" width="770" height="430" rx="18" fill="#dcead3" stroke="#8fae84" stroke-width="2"/><path d="M15 216H785M527 15V445M273 15V216" stroke="#c6b99a" stroke-width="21"/><path d="M15 216H785M527 15V445M273 15V216" stroke="#f3e9d0" stroke-width="2" stroke-dasharray="12 8"/>${sites.map(a=>`<g role="button" tabindex="0" aria-label="${esc(a.n)}" data-twin="${a.page}" style="cursor:pointer"><rect x="${a.x}" y="${a.y}" width="${a.w}" height="${a.h}" rx="13" fill="${a.c}" stroke="#78967b" stroke-width="2"/><rect x="${a.x+8}" y="${a.y+8}" width="${a.w-16}" height="${a.h-16}" rx="9" fill="none" stroke="#ffffff" stroke-opacity=".65" stroke-dasharray="5 5"/><g transform="translate(${a.x+a.w-83} ${a.y+21})" pointer-events="none">${a.page===7?'<path d="M0 28L32 10L65 28V58L32 76L0 58Z" fill="#b99b70"/><path d="M0 28L32 0L65 28L32 45Z" fill="#356649"/><path d="M32 45V76L65 58V28Z" fill="#8b7554"/>':a.page===3?'<path d="M0 35L45 10L72 29L27 54Z" fill="#28566c" stroke="#8db6c9" stroke-width="2"/><path d="M11 29L38 48M22 23L49 42M34 17L61 35M14 45L59 20" stroke="#a4c9d7"/><path d="M27 54V65M68 31V45" stroke="#47685d" stroke-width="3"/>':a.page===2?'<path d="M6 20V56C6 75 63 75 63 56V20" fill="#6aa9bd"/><ellipse cx="34.5" cy="20" rx="28.5" ry="12" fill="#c0e3ea" stroke="#6b9dad"/><path d="M63 56H73V67" stroke="#42768c" stroke-width="5" fill="none"/>':a.page===8?'<path d="M0 35L40 12L75 32L35 55Z" fill="#80b36a"/><path d="M0 35L35 55V64L0 44Z" fill="#5e8c4c"/><path d="M35 55L75 32V41L35 64Z" fill="#477a47"/>':'<path d="M0 40L34 20L68 40V62L34 82L0 62Z" fill="#92754b"/><path d="M0 40L34 60L68 40" fill="#baa375"/><path d="M10 38Q30 0 58 38Q35 59 10 38Z" fill="#627a45"/>'}</g><text x="${a.x+20}" y="${a.y+45}" font-size="30" fill="#246347">${a.icon}</text><text x="${a.x+20}" y="${a.y+80}" font-size="18" font-weight="bold" fill="#20372e">${esc(a.n)}</text><text x="${a.x+20}" y="${a.y+108}" font-size="15" fill="#385e4b">${esc(a.v)}</text><text x="${a.x+a.w-30}" y="${a.y+a.h-16}" font-size="19" fill="#246347">→</text></g>`).join('')}</svg><div class="grid">${sites.map(a=>`<button class="quick" onclick="go(${a.page})"><span>${a.icon}</span>${esc(a.n)}<b>→</b></button>`).join('')}<button class="quick" onclick="go(1)">♘ Atlaryň pasporty <b>→</b></button></div><p class="muted">Bu çyzgy hakyky GPS ýerleşişi ýa-da 3D model däl. Sanlar saklanan maglumatlardan alynýar; IoT enjamlary birikdirilmedi.</p></section><div class="grid">${card('Suw tygşytlamasy',fmt(m.w)+' L/gün','Başlangyç bilen deňeşdirme')}${card('Elektrik torundan azalyş',fmt(m.e)+' kWh/gün','Başlangyç bilen deňeşdirme')}${card('Komposta gönükdirilen ders',fmt(m.g)+' kg/gün','Girizilen maglumat')}${card('Suw bakynyň derejesi',fmt(data.stableSim.tank)+'%','Simulýasiýanyň başlangyç sazlamasy')}</div><button onclick="go(6)">Ekologik hasabaty aç →</button>`}

function reportModel(){const m=metrics(),d=reportDays,c=data.cost;return {days:d,waterBase:data.water.base*d/1000,waterNow:data.water.used*d/1000,waterSaved:m.w*d/1000,energyBase:data.energy.base*d,energyNow:(data.energy.used-data.energy.solar)*d,energySaved:m.e*d,wasteTotal:data.waste.total*d/1000,wasteCompost:m.g*d/1000,waterMoney:m.w*d/1000*c.water,energyMoney:m.e*d*c.energy}}
function reportPage(){const r=reportModel(),a=analysisModel(),p=pastureTotals(),rain=rainModel(),solar=solarModel(),comp=compostModel();return `<section class="hero"><h1>Ekologik we ykdysady hasabat</h1><p>EcoHorse · Smart & Green Technology 2026</p><span class="pill">Hasaplama we çaklama</span></section><section class="card"><div class="section-head"><h3>Hasaplama döwri</h3><span class="pill">${r.days} gün</span></div><div style="display:flex;gap:8px;flex-wrap:wrap">${[[1,'Gündelik'],[7,'Hepdelik'],[30,'30 günlük'],[365,'Ýyllyk']].map(([d,l])=>`<button class="${reportDays===d?'':'secondary'}" onclick="setReportDays(${d})" ${reportDays===d?'aria-pressed="true"':'aria-pressed="false" style="background:#e5efe3;color:#20563c"'}>${l}</button>`).join('')}</div><p class="muted" style="margin-top:12px">Gündelik girizilen sanlar saýlanan gün sanyna köpeldilýär. Hakyky taryhy ölçegleriň jemi däl.</p></section><div class="grid">${card('Suw tygşytlamasy',fmt(r.waterSaved)+' m³',r.days+' gün')}${card('Elektrik torundan azalyş',fmt(r.energySaved)+' kWh',r.days+' gün')}${card('Komposta gönükdirilen ders',fmt(r.wasteCompost)+' t',r.days+' gün')}${card('Çaklanylýan çykdajy azalyşy',fmt(r.waterMoney+r.energyMoney)+' TMT','Maýa we hyzmat çykdajylary aýrylmady')}</div><div class="cols home-charts">${compare('Suw sarp edilişi','m³',r.waterBase,r.waterNow,2)}${compare('Elektrik torundan sarp ediliş','kWh',r.energyBase,r.energyNow,3)}</div><section class="card"><h3>Ekologik görkezijiler</h3><div style="overflow-x:auto"><table><thead><tr><th>Görkeziji</th><th>Başlangyç / jemi</th><th>Häzirki / bölek</th><th>Netije</th></tr></thead><tbody><tr><td>Suw (m³)</td><td>${fmt(r.waterBase)}</td><td>${fmt(r.waterNow)}</td><td>${fmt(r.waterSaved)} tygşyt</td></tr><tr><td>Elektrik (kWh)</td><td>${fmt(r.energyBase)}</td><td>${fmt(r.energyNow)}</td><td>${fmt(r.energySaved)} azalyş</td></tr><tr><td>Ders (t)</td><td>${fmt(r.wasteTotal)}</td><td>${fmt(r.wasteCompost)}</td><td>${r.wasteTotal>0?fmt(pct(r.wasteCompost,r.wasteTotal))+'%':'—'} komposta</td></tr></tbody></table></div><p class="notice">Içerki Eco Score: ${a.score===null?'Maglumat ýeterlik däl':fmt(a.score)+' / 100'} (${a.covered}/3 ugur). Resmi ekologik baha däl.</p></section><section class="card" style="margin-top:18px"><h3>Ykdysady netijeler</h3><table><tbody><tr><td>Suw</td><td>${fmt(r.waterMoney)} TMT</td></tr><tr><td>Elektrik</td><td>${fmt(r.energyMoney)} TMT</td></tr><tr><th>Jemi çykdajy azalyşy</th><th>${fmt(r.waterMoney+r.energyMoney)} TMT</th></tr></tbody></table><p class="muted">Ulanyjy tarapyndan girizilen tarifler: suw ${fmt(data.cost.water)} TMT/m³; elektrik ${fmt(data.cost.energy)} TMT/kWh.</p></section><section class="card" style="margin-top:18px"><h3>Aýratyn ösüş ssenariýalary</h3><p>Ýagyş suwunyň ulanyş çaklamasy: ${fmt(rain.usable)} m³/ýyl; ${fmt(rain.money)} TMT/ýyl.</p><p>Täze Gün panelleri: ${fmt(solar.generation)} kWh/ýyl önümçilik; ${fmt(solar.used)} kWh/ýyl goşmaça elektrik azalyşy; ${fmt(solar.net)} TMT/ýyl arassa peýda.</p><p>Kompost (${data.compostPlan.days} gün): ${fmt(comp.output/1000)} t taýýar dökün; ${fmt(comp.net)} TMT amal netijesi.</p><p>Öri meýdanlary: ${fmt(p.area)} ga; dynç alýan meýdan ${fmt(p.rest)} ga; bir suwaryş ${fmt(p.water)} m³.</p><p>Hasaba alnan atlar: ${data.horses.length}.</p><p class="notice">Ssenariýalar esasy tygşytlylyga goşulmady. Iki gezek hasaplamagyň öňi alynýar. IoT maglumatlary simulýasiýa; hakyky ölçegler we tarifler tassyklanmaly.</p></section><section class="card" style="margin-top:18px"><h3>Hasabaty eksport etmek</h3><div style="display:flex;gap:8px;flex-wrap:wrap"><button onclick="window.print()">Çap et / PDF</button><button onclick="downloadCSV()">CSV eksport</button><button onclick="downloadReport()">JSON eksport</button><button class="danger" onclick="resetDemo()">Synag maglumatlaryny dikelt</button></div><p class="muted" style="margin-top:12px">PDF üçin brauzeriň çap penjiresinde PDF hökmünde saklamagy saýlaň.</p></section>`}
function downloadCSV(){const r=reportModel();const rows=[['Görkeziji','Bahasy','Birlik'],['Döwür',r.days,'gün'],['Başlangyç suw',r.waterBase,'m³'],['Häzirki suw',r.waterNow,'m³'],['Suw tygşytlamasy',r.waterSaved,'m³'],['Başlangyç elektrik',r.energyBase,'kWh'],['Häzirki elektrik',r.energyNow,'kWh'],['Elektrik azalyşy',r.energySaved,'kWh'],['Jemi ders',r.wasteTotal,'t'],['Komposta gönükdirilen ders',r.wasteCompost,'t'],['Suw çykdajy azalyşy',r.waterMoney,'TMT'],['Elektrik çykdajy azalyşy',r.energyMoney,'TMT'],['Jemi çykdajy azalyşy',r.waterMoney+r.energyMoney,'TMT'],['Bellik','Gündelik sanlardan hasaplanan çaklama','']];const csv=rows.map(row=>row.map(v=>'"'+String(typeof v==='number'?Number(v.toFixed(4)):v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='ecohorse-'+r.days+'-gun.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}


function pitchSlides(){const m=metrics(),c=data.cost,a=analysisModel();return [
{tag:'01 / Taslama',title:'Bedewler bilen ýaşyl geljege',desc:'EcoHorse — atçylyk toplumlary üçin akylly we ýaşyl dolandyryş ulgamy.',body:'<p>Atçylyk, ekologiýa we ykdysadyýet bir sanly ulgamda.</p>',link:0,time:'40 sekunt'},
{tag:'02 / Mesele',title:'Serişdeleriň netijeli dolandyrylmagy',desc:'Suwuň, elektrik energiýasynyň we organiki galyndylaryň hasabyny bitewi görnüşde ýöretmek.',body:'<p>Mesele: dürli maglumatlaryň aýry-aýry saklanmagy, isripleri ýüze çykarmagyň kynlygy we ekologik peýdany ölçemek zerurlygy.</p>',link:5,time:'45 sekunt'},
{tag:'03 / Çözgüt',title:'Bitewi sanly atçylyk toplumy',desc:'Sanly at pasportlary, suw, energiýa, kompost, öri meýdanlary we athana datçikleriniň simulýasiýasy.',body:'<p>Interaktiw Digital Twin çyzgysy arkaly ähli bölümlere geçmek mümkin.</p>',link:10,time:'55 sekunt'},
{tag:'04 / Green',title:'Ekologik peýdanyň ölçegi',desc:'Girizilen gündelik maglumatlar boýunça 365 günlük çaklama.',body:'<div class="grid">'+card('Suw tygşytlamasy',fmt(m.w*365/1000)+' m³','Ýyllyk çaklama')+card('Elektrik torundan azalyş',fmt(m.e*365)+' kWh','Ýyllyk çaklama')+card('Komposta gönükdirilen ders',fmt(m.g*365/1000)+' t','Ýyllyk çaklama')+'</div>',link:6,time:'65 sekunt'},
{tag:'05 / Smart',title:'Akylly athana we seljerme',desc:'Datçik simulýasiýasy, duýduryşlar we ileri tutulmaly işler.',body:'<div class="grid">'+card('Içerki Eco Score',a.score===null?'—':fmt(a.score)+' / 100','Saýlanan maksatlara ýetiliş')+card('Ilkinji nobatda barlamaly',a.items.filter(x=>x.priority===0).length,'Düzgünlere esaslanýan seljerme')+'</div><p>Hakyky IoT enjamlary ýa-da daşarky AI modeli birikdirilmedi.</p>',link:7,time:'60 sekunt'},
{tag:'06 / Ykdysadyýet',title:'Çykdajylary azaltmak mümkinçiligi',desc:'Suw we elektrik tygşytlylygynyň ykdysady çaklamasy.',body:'<div class="grid">'+card('Ýyllyk çykdajy azalyşy',fmt((m.w/1000*c.water+m.e*c.energy)*365)+' TMT','Maýa we hyzmat çykdajylary aýrylmady')+card('Gün panelleri',solarModel().payback===null?'—':fmt(solarModel().payback)+' ýyl','Aýratyn öwezini doluş çaklamasy')+'</div><p>Kompost, ýagyş suwy we täze Gün panelleri esasy tygşytlylyga goşulmaýar.</p>',link:9,time:'55 sekunt'},
{tag:'07 / Tehnologiýa',title:'Işleýän web prototipi',desc:'HTML, CSS, JavaScript, localStorage, SVG, GitHub we Render.',body:'<p>Kod taýýarlamakda OpenAI ChatGPT ulanyldy. Ulgam düzgünlere esaslanýar. Maglumatlar şol brauzerde saklanýar; merkezi maglumatlar binýady ýok.</p>',link:1,time:'40 sekunt'},
{tag:'08 / Geljek',title:'Synagdan hakyky atçylyk toplumyna',desc:'Hakyky ölçegleri toplamak, IoT enjamlaryny birikdirmek we netijeleri barlamak.',body:'<p>Indiki maksat: pilot toplumda ekologik we ykdysady netijeleri ölçemek, maglumatlaryň hilini tassyklamak we merkezi ulgam döretmek.</p><p><strong>Bedewler bilen ýaşyl geljege!</strong></p>',link:6,time:'40 sekunt'}
]}
function presentation(){const slides=pitchSlides(),p=slides[presentationIndex];return `<section id="pitchStage" class="card" style="min-height:490px;padding:clamp(18px,4vw,48px);background:#f5f8f1;overflow:auto"><div class="section-head"><span class="pill">${p.tag}</span><span class="muted">${presentationIndex+1} / ${slides.length} · ${p.time}</span></div><div class="bar"><i style="width:${(presentationIndex+1)/slides.length*100}%"></i></div><h1 style="font-size:clamp(28px,5vw,54px);line-height:1.12;color:#20563c;margin:28px 0 18px">${p.title}</h1><p style="font-size:clamp(16px,2.5vw,24px);line-height:1.5">${p.desc}</p><div style="margin:26px 0;font-size:18px">${p.body}</div><p class="notice">Görkezilýän sanlar synag ýa-da ulanyjy maglumatlaryna esaslanýan çaklamalardyr; ölçenen ekologik netije däl.</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:22px"><button onclick="pitchMove(-1)" ${presentationIndex===0?'disabled':''}>← Öňki</button><button onclick="pitchMove(1)" ${presentationIndex===slides.length-1?'disabled':''}>Indiki →</button><button onclick="pitchFullscreen()">Doly ekran</button><button onclick="openPitchModule(${p.link})">Moduly görkez</button><button onclick="pitchMove(0)">Başa dolan</button></div></section><p class="muted">Tanyşdyryş meýilnamasy: takmynan 6 minut 40 sekunt. Klawiaturanyň çep we sag peýkam düwmeleri bilen geçiň.</p>`}

function render(){let m=metrics(),s=data.stable,c=data.cost,html='';$('heading').textContent=names[page];$('nav').innerHTML=names.map((n,i)=>`<button class="${i===page?'active':''}" ${i===page?'aria-current="page"':''} onclick="go(${i})">${icons[i]} &nbsp; ${n}</button>`).join('');
switch(page){case 0:html=dashboard();break;case 1:html=horses();break;case 2:html=cards()+fields('water')+`<p class="notice">Ýyllyk çaklama: ${fmt(m.w*365/1000)} m³. Atlaryň agyz suwuny çäklendirmäň.</p>`;html+=waterLab();break;case 3:html=cards()+fields('energy')+'<p class="notice">Elektrik torundan alynýan energiýa = häzirki sarp ediliş − Gün energiýasy. Başlangyçda Gün energiýasy ýok diýlip kabul edilýär.</p>'+solarLab();break;case 4:html=cards()+fields('waste')+`<p class="notice">Komposta gönükdirilen paý: ${fmt(m.pg)}%. Bu taýýar kompostyň agramy däl.</p>`+compostLab();break;case 5:html=cards()+analysis();break;case 6:html=reportPage();break;case 7:html=`<div class="notice">IoT simulýasiýasy: hakyky datçik birikdirilmedik.</div><div class="grid">${card('Temperatura',fmt(s.temperature)+' °C',s.temperature>s.limitTemp?'Bellenen çäkden ýokary':'Bellenen çäkde')}${card('Çyglylyk',fmt(s.humidity)+'%',s.humidity>s.limitHumidity?'Bellenen çäkden ýokary':'Bellenen çäkde')}</div>${fields('stable')}<p class="notice">Çäkler weterinariýa standarty däl.</p>`+stableLab();break;case 8:html=pasture();break;case 9:{let w=m.w*c.days/1000*c.water,e=m.e*c.days*c.energy;html=`<div class="grid">${card('Suw boýunça peýda',fmt(w)+' TMT','Saýlanan döwür')}${card('Elektrik boýunça peýda',fmt(e)+' TMT','Saýlanan döwür')}${card('Jemi çaklama',fmt(w+e)+' TMT','Maýa we hyzmat çykdajylary aýrylmady')}</div>${fields('cost')}<p class="notice">Bahalar mysal. Hakyky tarifleri giriziň.</p>`;break;}case 10:html=twin();break;case 11:html=presentation();break;}
$('app').innerHTML=(storageWarning?'<p class="notice" role="alert">Brauzeriň ýerli ýady bilen mesele ýüze çykdy. Maglumatlary eksport ediň.</p>':'')+html;document.querySelectorAll('[data-twin]').forEach(el=>{const open=()=>go(Number(el.dataset.twin));el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});let f=$('form');if(f)f.onsubmit=e=>{e.preventDefault();let k=f.dataset.key,v=Object.fromEntries([...new FormData(f)].map(([n,x])=>[n,Number(x)]));if(Object.values(v).some(x=>!Number.isFinite(x))||(k==='energy'&&v.solar>v.used)||(k==='waste'&&v.compost>v.total)){$('err').textContent='Bölek jemi mukdardan uly bolup bilmez.';return}data[k]=v;if(k==='stable')resetStableSim();save();render()};let gf=$('goalsForm');if(gf)gf.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries([...new FormData(gf)].map(([k,x])=>[k,Number(x)]));if(Object.values(v).some(x=>!Number.isFinite(x)||x<1||x>100))return;data.analysisGoals=v;save();render()};let stf=$('stableSimForm');if(stf){stf.onsubmit=e=>{e.preventDefault();data.stableSim=Object.fromEntries([...new FormData(stf)].map(([k,v])=>[k,Number(v)]));save();resetStableSim();render()};drawStable()}let cf=$('compostForm');if(cf)cf.onsubmit=e=>{e.preventDefault();data.compostPlan=Object.fromEntries([...new FormData(cf)].map(([k,v])=>[k,Number(v)]));save();render()};let sf=$('solarForm');if(sf)sf.onsubmit=e=>{e.preventDefault();data.solarPlan=Object.fromEntries([...new FormData(sf)].map(([k,v])=>[k,Number(v)]));save();render()};let rf=$('rainForm');if(rf)rf.onsubmit=e=>{e.preventDefault();data.rain=Object.fromEntries([...new FormData(rf)].map(([k,v])=>[k,Number(v)]));save();render()};let sc=$('scenario');if(sc)sc.oninput=()=>{let p=Number(sc.value),v=data.water.used*p/100*365/1000;$('scenarioPct').textContent=p+'%';$('scenarioWater').textContent=fmt(v)+' m³';$('scenarioMoney').textContent=fmt(v*data.cost.water)+' TMT'};let q=$('horseSearch');if(q)q.onsubmit=e=>{e.preventDefault();search=$('horseQuery').value.trim();render()};let hf=$('horseForm');if(hf){let photo=horsePhoto(data.horses[edit]||{}),busy=false;const file=$('horsePhoto'),preview=$('horsePreview'),error=$('photoError');file.onchange=async()=>{if(!file.files[0])return;busy=true;file.disabled=true;$('clearHorsePhoto').disabled=true;try{photo=await readHorsePhoto(file.files[0]);preview.innerHTML=horsePicture({photo});error.textContent='Surat taýýar.'}catch(e){error.textContent=e.message}finally{busy=false;file.disabled=false;$('clearHorsePhoto').disabled=false}};$('clearHorsePhoto').onclick=()=>{photo='';file.value='';preview.innerHTML=horsePicture({});error.textContent='Surat aýryldy.'};hf.onsubmit=e=>{e.preventDefault();if(busy)return;let h=Object.fromEntries(new FormData(hf));if(!h.name.trim()||!h.breed.trim())return;h.photo=photo;const old=data.horses.slice();if(edit<0)data.horses.push(h);else data.horses[edit]=h;save();if(storageWarning){data.horses=old;error.textContent='Ýatda ýer ýeterlik däl. Has kiçi surat saýlaň.';return}edit=-1;render()}};let p=$('pastureForm');if(p)p.onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(p));v.name=v.name.trim();v.area=Number(v.area);v.count=Number(v.count);v.irrigation=Number(v.irrigation);if(!v.name||!Number.isFinite(v.area)||v.area<=0||!Number.isInteger(v.count)||v.count<0||!Number.isFinite(v.irrigation)||v.irrigation<0){$('pastureError').textContent='Maglumatlary barlaň.';return}if(v.status!=='active'&&v.count>0){$('pastureError').textContent='Dynç alýan ýa-da ýapyk meýdana at paýlamaň.';return}if(pastureEdit<0)data.pasture.push(v);else data.pasture[pastureEdit]=v;pastureEdit=-1;save();render()}}
Object.assign(window,{pitchMove(step){presentationIndex=step===0?0:Math.max(0,Math.min(pitchSlides().length-1,presentationIndex+step));const stage=$('pitchStage');if(stage&&document.fullscreenElement===stage){const tmp=document.createElement('div');tmp.innerHTML=presentation();stage.innerHTML=tmp.querySelector('#pitchStage').innerHTML}else render()},async pitchFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if($('pitchStage')?.requestFullscreen)await $('pitchStage').requestFullscreen()}catch{alert('Doly ekran bu brauzerde elýeterli däl.')}},async openPitchModule(i){if(document.fullscreenElement)await document.exitFullscreen();go(i)},setReportDays(d){if([1,7,30,365].includes(d)){reportDays=d;render()}},downloadCSV,editPasture(i){pastureEdit=i;render()},cancelPasture(){pastureEdit=-1;render()},startStableSim,stopStableSim,resetStableSim,stableScenario,clearSearch(){search='';render()},showPassport(i){const h=data.horses[i];if(!h)return;const d=document.createElement('dialog');d.style.cssText='border:1px solid #dfe7de;border-radius:18px;padding:26px;width:min(560px,92vw);color:#20372e';d.innerHTML=`<h2>♘ EcoHorse — Sanly pasport</h2><div class="passport-cover">${horsePicture(h)}<h3>${esc(h.name)}</h3><p class="muted">${esc(h.breed)}</p></div><table>${horseFields.map(([key,label])=>`<tr><th>${label}</th><td>${esc(h[key]||'—')}</td></tr>`).join('')}</table><p class="muted">Ulanyjy tarapyndan girizilen maglumatlar. Resmi döwlet pasporty däl.</p><button id="closePassport">Ýap</button>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()},go(i){stopStableSim();edit=-1;pastureEdit=-1;page=i;render()},editHorse(i){edit=i;render()},removeHorse(i){if(confirm('Aty sanawdan pozmalymy?')){data.horses.splice(i,1);save();render()}},removePasture(i){if(confirm('Meýdany pozmalymy?')){data.pasture.splice(i,1);pastureEdit=-1;save();render()}},resetDemo(){if(confirm('Ähli üýtgeşmeleri aýyrmalymy?')){data=structuredClone(defaults);edit=-1;pastureEdit=-1;search='';reportDays=365;presentationIndex=0;resetStableSim();save();render()}},downloadReport(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({type:'demo or user entered',data,metrics:metrics(),periodReport:reportModel(),analysis:analysisModel(),scenarios:{rain:rainModel(),solar:solarModel(),compost:compostModel(),pasture:pastureTotals()}},null,2)],{type:'application/json'}));a.download='ecohorse-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}});
document.addEventListener('keydown',e=>{if(page!==11||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();window.pitchMove(e.key==='ArrowRight'?1:-1)}});
render();
})();
